/* Modal de confirmación de borrado (SRCH-03). Solo `var(--bw-*)`. */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--bw-sidebar-overlay);
}

.modal {
  /* El mock pinta el modal en blanco puro; no hay token de blanco, así que se
     usa el neutro más claro de la paleta (--bw-warm-cream). */
  width: 420px;
  max-width: 90vw;
  padding: 28px;
  border-radius: 8px;
  background: var(--bw-warm-cream);
  box-shadow: 0 20px 60px var(--bw-sidebar-overlay);
}

.icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  margin-bottom: 14px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 50%;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 20px;
}

.title {
  margin: 0 0 14px;
  font-family: var(--bw-font-title);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.45;
  color: var(--bw-deep-steel);
}

.error {
  margin: 0 0 14px;
  padding: 8px 10px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-family: var(--bw-font-body);
  font-size: 12px;
}

.buttons {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.cancel {
  padding: 8px 18px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-ink-steel);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: border-color 0.12s;
}

.cancel:hover {
  border-color: var(--bw-hover-border);
}

.confirm {
  padding: 8px 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-danger);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.12s;
}

.confirm:hover:not(:disabled) {
  background: var(--bw-sensitive-text);
}

.confirm:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

import styles from './DeleteWatcherModal.module.css';

interface Props {
  partNumber: string;
  busy: boolean;
  error: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

const TITLE_ID = 'delete-watcher-modal-title';

/**
 * Confirmación de borrado (spec §6). El borrado es irreversible —no hay papelera—
 * así que `Eliminar` NUNCA se ejecuta sin pasar por aquí. Totalmente controlado:
 * se cierra con `Cancelar`, no con clic fuera.
 */
export function DeleteWatcherModal({ partNumber, busy, error, onConfirm, onCancel }: Props) {
  return (
    <div className={styles.overlay} role="dialog" aria-modal="true" aria-labelledby={TITLE_ID}>
      <div className={styles.modal}>
        <div className={styles.icon} aria-hidden="true">
          <i className="ti ti-trash" />
        </div>
        <h2 className={styles.title} id={TITLE_ID}>
          {`¿Eliminar el watcher de ${partNumber}? Esta acción no se puede deshacer.`}
        </h2>

        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}

        <div className={styles.buttons}>
          <button type="button" className={styles.cancel} onClick={onCancel}>
            Cancelar
          </button>
          <button type="button" className={styles.confirm} disabled={busy} onClick={onConfirm}>
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}

