import {
  conditionsLabel,
  daysLeftLabel,
  daysTone,
  expiresInLabel,
  sinceLabel,
  triggeredLabel,
  type WatcherRow,
  type WatcherState,
} from '../../lib/watchers';
import styles from './WatcherCard.module.css';

interface Props {
  row: WatcherRow;
  /** Inyectable para que los tests no dependan del reloj. */
  now: Date;
  /** Con una llamada en vuelo, TODOS los botones van `disabled`. */
  busy: boolean;
  onPause: (row: WatcherRow) => void;
  onResume: (row: WatcherRow) => void;
  onEdit: (row: WatcherRow) => void;
  onDelete: (row: WatcherRow) => void;
  onRenew: (row: WatcherRow) => void;
  onLetExpire: (row: WatcherRow) => void;
  onViewResults: (row: WatcherRow) => void;
}

/** Los cinco estados con su color: el borde izquierdo de la tarjeta y el badge. */
const STATE_CLASS: Record<WatcherState, string> = {
  ACTIVE: styles.stateActive,
  PAUSED: styles.statePaused,
  TRIGGERED: styles.stateTriggered,
  'PENDIENTE RENOVACIÓN': styles.stateRenewal,
  EXPIRED: styles.stateExpired,
};

const BADGE_CLASS: Record<WatcherState, string> = {
  ACTIVE: styles.badgeActive,
  PAUSED: styles.badgePaused,
  TRIGGERED: styles.badgeTriggered,
  'PENDIENTE RENOVACIÓN': styles.badgeRenewal,
  EXPIRED: styles.badgeExpired,
};

/**
 * Tarjeta de un watcher. Presentacional: sin red y sin estado, y sin reimplementar
 * nada de `lib/watchers.ts` — las etiquetas, los días y el tono salen de allí.
 */
export function WatcherCard({
  row,
  now,
  busy,
  onPause,
  onResume,
  onEdit,
  onDelete,
  onRenew,
  onLetExpire,
  onViewResults,
}: Props) {
  const stateClass = STATE_CLASS[row.state];
  const badgeClass = BADGE_CLASS[row.state];

  const withDays = row.state === 'ACTIVE' || row.state === 'PAUSED';
  const isRenewal = row.state === 'PENDIENTE RENOVACIÓN';
  const isTriggered = row.state === 'TRIGGERED';
  const triggered = triggeredLabel(row);

  return (
    <article
      className={`${styles.card} ${stateClass}`}
      aria-label={'Watcher ' + row.partNumber}
      data-state={row.state}
    >
      <div className={styles.head}>
        <span className={styles.ref}>{row.partNumber}</span>
        {/* El estado va TAL CUAL: la capa de datos ya traduce `PENDIENTE RENOVACION`. */}
        <span className={`${styles.badge} ${badgeClass}`}>{row.state}</span>
      </div>

      <p className={styles.conditions}>{conditionsLabel(row)}</p>

      <p className={styles.created}>
        {'Creado: '}
        {sinceLabel(row.createdAt, now)}
      </p>

      <div className={styles.meta}>
        {/* Días restantes: SOLO en ACTIVE y PAUSED. */}
        {withDays && (
          <span className={styles.days} data-tone={daysTone(row.daysRemaining ?? 0)}>
            {daysLeftLabel(row.daysRemaining ?? 0, row.state === 'PAUSED')}
          </span>
        )}
        {/* PENDIENTE RENOVACIÓN: cuenta atrás para decidir, no días restantes. */}
        {isRenewal && (
          <span className={styles.daysRenewal}>{expiresInLabel(row.renewalDaysLeft ?? 0)}</span>
        )}

        <span className={styles.channels}>
          <span className={styles.channel}>
            <i className={`ti ti-bell ${styles.channelIcon}`} aria-hidden="true" />
            In-app
          </span>
          {row.emailChannel && (
            <span className={styles.channel}>
              <i className={`ti ti-mail ${styles.channelIcon}`} aria-hidden="true" />
              Email
            </span>
          )}
        </span>
      </div>

      {isTriggered && triggered !== null && (
        <p className={styles.triggered}>
          <i className={`ti ti-bell-ringing ${styles.triggeredIcon}`} aria-hidden="true" />
          {triggered}
        </p>
      )}

      {isRenewal && (
        <div className={styles.renewal}>
          <button
            type="button"
            className={styles.renewButton}
            disabled={busy}
            onClick={() => onRenew(row)}
          >
            Mantener activo 30 días más
          </button>
          <button
            type="button"
            className={styles.expireButton}
            disabled={busy}
            onClick={() => onLetExpire(row)}
          >
            Dejar que expire
          </button>
        </div>
      )}

      <div className={styles.actions}>
        {isTriggered && (
          <button
            type="button"
            className={styles.primary}
            disabled={busy}
            onClick={() => onViewResults(row)}
          >
            Ver resultados
          </button>
        )}

        {row.state === 'ACTIVE' && (
          <button
            type="button"
            className={styles.action}
            aria-label={`Pausar — ${row.partNumber}`}
            disabled={busy}
            onClick={() => onPause(row)}
          >
            Pausar
          </button>
        )}

        {row.state === 'PAUSED' && (
          <button
            type="button"
            className={styles.action}
            aria-label={`Reactivar — ${row.partNumber}`}
            disabled={busy}
            onClick={() => onResume(row)}
          >
            Reactivar
          </button>
        )}

        {withDays && (
          <button
            type="button"
            className={styles.action}
            aria-label={`Editar — ${row.partNumber}`}
            disabled={busy}
            onClick={() => onEdit(row)}
          >
            Editar
          </button>
        )}

        <button
          type="button"
          className={`${styles.action} ${styles.actionDanger}`}
          aria-label={`Eliminar — ${row.partNumber}`}
          disabled={busy}
          onClick={() => onDelete(row)}
        >
          Eliminar
        </button>
      </div>
    </article>
  );
}

