import {
  WATCHER_COUNTRY_OPTIONS,
  isValidWatcherDraft,
  type WatcherDraft,
} from '../../lib/watchers';
import styles from './WatcherEditForm.module.css';

interface Props {
  /** La referencia ORIGINAL de la fila: da nombre al formulario y a sus `id`. */
  partNumber: string;
  draft: WatcherDraft;
  busy: boolean;
  error: string | null;
  /** Cada cambio entrega el borrador ENTERO; el formulario no guarda nada. */
  onChange: (draft: WatcherDraft) => void;
  onSave: () => void;
  onCancel: () => void;
}

/**
 * `Editar watcher` (spec §4). Totalmente controlado: el estado y la red viven en
 * la pantalla. La validación es la de `lib/watchers.ts`, no una copia local.
 */
export function WatcherEditForm({
  partNumber,
  draft,
  busy,
  error,
  onChange,
  onSave,
  onCancel,
}: Props) {
  // Solo hay un formulario abierto a la vez, así que los `id` son únicos por
  // referencia y no hace falta un contador global.
  const base = `watcher-edit-${partNumber.replace(/[^A-Za-z0-9_-]/g, '-')}`;
  const saveDisabled = !isValidWatcherDraft(draft) || busy;

  return (
    <form
      className={styles.form}
      aria-label={'Editar watcher ' + partNumber}
      onSubmit={(event) => {
        event.preventDefault();
        onSave();
      }}
    >
      <div className={styles.grid}>
        <div className={styles.field}>
          <label className={styles.label} htmlFor={`${base}-ref`}>
            Referencia
          </label>
          <input
            id={`${base}-ref`}
            className={styles.input}
            type="text"
            placeholder="Ej: 6308-ZZ"
            value={draft.partNumber}
            onChange={(event) => onChange({ ...draft, partNumber: event.target.value })}
          />
          <p className={styles.hint}>Código exacto del rodamiento</p>
        </div>

        <div className={styles.field}>
          <label className={styles.label} htmlFor={`${base}-qty`}>
            Cantidad mínima
          </label>
          <input
            id={`${base}-qty`}
            className={styles.input}
            type="number"
            placeholder="Ej: 100"
            value={draft.minQuantity}
            onChange={(event) => onChange({ ...draft, minQuantity: event.target.value })}
          />
          <p className={styles.hint}>Unidades mínimas para que se dispare</p>
        </div>

        <div className={styles.field}>
          <label className={styles.label} htmlFor={`${base}-brand`}>
            Marca
          </label>
          <input
            id={`${base}-brand`}
            className={styles.input}
            type="text"
            placeholder="Cualquier marca"
            value={draft.brand}
            onChange={(event) => onChange({ ...draft, brand: event.target.value })}
          />
          <p className={styles.hint}>Opcional — deja vacío para cualquier fabricante</p>
        </div>

        <div className={styles.field}>
          <label className={styles.label} htmlFor={`${base}-country`}>
            País
          </label>
          <select
            id={`${base}-country`}
            className={styles.input}
            value={draft.country}
            onChange={(event) => onChange({ ...draft, country: event.target.value })}
          >
            <option value="">Cualquier país</option>
            {/* La lista ISO ya viene ordenada por nombre desde la capa de datos. */}
            {WATCHER_COUNTRY_OPTIONS.map((option) => (
              <option key={option.code} value={option.code}>
                {option.label}
              </option>
            ))}
          </select>
          <p className={styles.hint}>Opcional — deja vacío para cualquier origen</p>
        </div>
      </div>

      <div className={styles.checkField}>
        <div className={styles.checkRow}>
          <input
            id={`${base}-email`}
            className={styles.checkbox}
            type="checkbox"
            checked={draft.emailChannel}
            onChange={(event) => onChange({ ...draft, emailChannel: event.target.checked })}
          />
          <label className={styles.checkLabel} htmlFor={`${base}-email`}>
            Canal email
          </label>
        </div>
        <p className={styles.hint}>Recibirás también una notificación por email</p>
      </div>

      {error !== null && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      <div className={styles.buttons}>
        <button type="submit" className={styles.save} disabled={saveDisabled}>
          Guardar cambios
        </button>
        <button type="button" className={styles.cancel} onClick={onCancel}>
          Cancelar
        </button>
      </div>
    </form>
  );
}

