/* Panel de contenido de SRCH-03 (Gestión de Watchers), dentro del shell estándar.
   Ningún color literal: todo sale de las variables `--bw-*` del design system. */

/* Raíz de pantalla: hija DIRECTA de `.bwcnt`, que es `overflow: hidden`. Sin el
   `flex: 1; min-height: 0; overflow-y: auto` la lista se recorta sin barra de
   scroll con la ventana baja (F-186/F-189/F-190, patrón de `Forum.module.css`). */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
  margin: 0 0 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-family: var(--bw-font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  max-width: 580px;
  margin: 0 0 16px;
}

.status {
  margin: 0 0 12px;
  padding: 8px 12px;
  border-radius: var(--bw-radius);
  border: 1px solid var(--bw-tag-border);
  background: var(--bw-tag-bg);
  color: var(--bw-deep-steel);
  font-family: var(--bw-font-body);
  font-size: 13px;
}

.alert {
  margin: 0 0 12px;
  padding: 10px 12px;
  border-radius: var(--bw-radius);
  border: 1px solid var(--bw-badge-danger-border);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-family: var(--bw-font-body);
  font-size: 13px;
}

.counterRow {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.counter {
  display: inline-block;
  font-family: var(--bw-font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  padding: 4px 12px;
  border-radius: 20px;
}

/* El contenido de las variables lo pone React en `data-tone`, no el CSS. */
.counter[data-tone='brass'] {
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border-strong);
  color: var(--bw-brass);
}

.counter[data-tone='danger'] {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 16px;
}

.chip {
  padding: 5px 13px;
  border-radius: 20px;
  border: 1px solid var(--bw-line-steel-strong);
  background: var(--bw-warm-cream);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-body);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}

.chip:hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.chip[aria-pressed='true'] {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

/* El contador del chip forma parte de su nombre accesible: 'Todos 5'. */
.chipCount {
  font-family: var(--bw-font-mono);
  font-weight: 500;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.listItem {
  display: block;
}

.emptyTitle {
  font-family: var(--bw-font-body);
  font-size: 15px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  margin: 12px 0 6px;
}

.emptyBody {
  font-family: var(--bw-font-body);
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
  max-width: 560px;
  margin: 0;
}

.loading {
  font-family: var(--bw-font-body);
  font-size: 13px;
  color: var(--bw-steel-mist);
  margin: 12px 0;
}

