import { useEffect, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import type { SearchCriteria } from '../../lib/search';
import {
  DEFAULT_WATCHER_FILTER,
  WATCHER_FILTERS,
  activeCounterLabel,
  counterTone,
  deleteWatcher,
  draftFromRow,
  fetchWatchers,
  filterWatchers,
  letWatcherExpire,
  renewWatcher,
  setWatcherPaused,
  updateWatcher,
  watcherFilterCount,
  watcherToCriteria,
  type WatcherDraft,
  type WatcherFilterKey,
  type WatcherRow,
} from '../../lib/watchers';
import { DeleteWatcherModal } from './DeleteWatcherModal';
import { WatcherCard } from './WatcherCard';
import { WatcherEditForm } from './WatcherEditForm';
import styles from './Watchers.module.css';

const EYEBROW = 'Módulo 03 · Búsqueda Conversacional';
const TITLE = 'Mis watchers';
const SUBTITLE =
  'Los watchers te avisan cuando aparece stock de una referencia que buscas. Cada watcher está activo durante 30 días y puedes renovarlo.';

interface Props {
  /**
   * La sesión del miembro. SRCH-03 no la usa: la RLS de `0035` ya limita la vista
   * `watcher_list` a la organización de quien mira. Va en la firma porque es el
   * contrato de las pantallas de miembro, igual que en el resto.
   */
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj (INV-01/SRCH-01/PANEL-01). */
  now?: Date;
  /** Abre SRCH-01 con los criterios del watcher precargados. */
  onViewResults: (criteria: SearchCriteria) => void;
}

export function Watchers({ now, onViewResults }: Props) {
  /** La lista COMPLETA, tal como la entrega la capa de datos: los chips filtran en cliente. */
  const [rows, setRows] = useState<WatcherRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  /** El error de una ACCIÓN (pausar, editar, eliminar…), distinto del de la carga. */
  const [actionError, setActionError] = useState<string | null>(null);
  /** El aviso de éxito, uno solo a la vez, bajo el subtítulo. */
  const [status, setStatus] = useState<string | null>(null);

  const [filter, setFilter] = useState<WatcherFilterKey>(DEFAULT_WATCHER_FILTER);
  const [busy, setBusy] = useState(false);

  /** Solo una tarjeta en edición a la vez: `editingId` y su borrador viajan juntos. */
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState<WatcherDraft | null>(null);
  const [editError, setEditError] = useState<string | null>(null);

  /** El watcher pendiente de confirmación de borrado. `null` = modal cerrado. */
  const [deleting, setDeleting] = useState<WatcherRow | null>(null);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  /*
   * Una sola vez al montar. `now` NO entra en el efecto a propósito: la capa de
   * datos no lo recibe, así que depender de él solo volvería a consultar la base
   * en cada render (el bucle que documenta `Panel.tsx`, F-079). `now` formatea,
   * no consulta.
   */
  useEffect(() => {
    let active = true;

    fetchWatchers()
      .then((next) => {
        if (!active) return;
        setRows(next);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
        setLoading(false);
      });

    return () => {
      active = false;
    };
  }, []);

  const currentTime = now ?? new Date();
  const visible = filterWatchers(rows, filter);

  /**
   * El patrón de TODAS las acciones de la tarjeta: fuera aviso y error anteriores,
   * `busy` mientras la llamada está en vuelo, y al volver bien se REPIDE la lista
   * (la acción cambia el estado efectivo en la base) y se deja el aviso. Si falla,
   * el error va al `<p role="alert">` de la pantalla y ni se repide ni hay aviso.
   */
  async function runAction(row: WatcherRow, action: () => Promise<void>, message: string) {
    setStatus(null);
    setActionError(null);
    setBusy(true);
    try {
      await action();
      const next = await fetchWatchers();
      setRows(next);
      setStatus(message);
    } catch (e: unknown) {
      setActionError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  function pause(row: WatcherRow) {
    void runAction(row, () => setWatcherPaused(row.id, true), `Watcher de ${row.partNumber} pausado.`);
  }

  function resume(row: WatcherRow) {
    void runAction(row, () => setWatcherPaused(row.id, false), `Watcher de ${row.partNumber} reactivado.`);
  }

  function renew(row: WatcherRow) {
    void runAction(row, () => renewWatcher(row.id), `Watcher de ${row.partNumber} renovado por 30 días más.`);
  }

  function letExpire(row: WatcherRow) {
    void runAction(row, () => letWatcherExpire(row.id), `Watcher de ${row.partNumber} expirado.`);
  }

  function viewResults(row: WatcherRow) {
    onViewResults(watcherToCriteria(row));
  }

  /** Editar otra tarjeta cierra la anterior: `editingId` es único. */
  function startEdit(row: WatcherRow) {
    setEditingId(row.id);
    setDraft(draftFromRow(row));
    setEditError(null);
    setStatus(null);
    setActionError(null);
  }

  function cancelEdit() {
    setEditingId(null);
    setDraft(null);
    setEditError(null);
  }

  async function saveEdit(row: WatcherRow) {
    if (draft === null) return;
    setEditError(null);
    setBusy(true);
    try {
      await updateWatcher(row.id, draft);
      const next = await fetchWatchers();
      setRows(next);
      setEditingId(null);
      setDraft(null);
      setEditError(null);
      setStatus(`Watcher de ${row.partNumber} actualizado.`);
    } catch (e: unknown) {
      // El formulario SIGUE abierto con el mensaje dentro.
      setEditError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  /** `Eliminar` NUNCA borra: abre la confirmación (spec §6). */
  function requestDelete(row: WatcherRow) {
    setDeleting(row);
    setDeleteError(null);
    setStatus(null);
    setActionError(null);
  }

  function cancelDelete() {
    setDeleting(null);
    setDeleteError(null);
  }

  async function confirmDelete() {
    if (deleting === null) return;
    const row = deleting;
    setDeleteError(null);
    setBusy(true);
    try {
      await deleteWatcher(row.id);
      const next = await fetchWatchers();
      setRows(next);
      setDeleting(null);
      setDeleteError(null);
      setStatus(`Watcher de ${row.partNumber} eliminado.`);
    } catch (e: unknown) {
      // El modal SIGUE abierto con el error dentro.
      setDeleteError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  function renderList() {
    // Lista COMPLETA vacía: primer acceso (spec §6).
    if (rows.length === 0) {
      return (
        <>
          <p className={styles.emptyTitle}>Todavía no tienes ningún watcher activo.</p>
          <p className={styles.emptyBody}>
            Crea un watcher desde la búsqueda cuando no encuentres stock de una referencia — te
            avisaremos cuando aparezca.
          </p>
        </>
      );
    }

    // Hay watchers, pero ninguno en el chip activo.
    if (visible.length === 0) {
      return <p className={styles.emptyTitle}>No hay watchers en este estado.</p>;
    }

    return (
      <ul className={styles.list} aria-label="Lista de watchers">
        {visible.map((row) => (
          <li key={row.id} className={styles.listItem}>
            <WatcherCard
              row={row}
              now={currentTime}
              busy={busy}
              onPause={pause}
              onResume={resume}
              onEdit={startEdit}
              onDelete={requestDelete}
              onRenew={renew}
              onLetExpire={letExpire}
              onViewResults={viewResults}
            />
            {/* El formulario va en el MISMO `<li>`, justo después de la tarjeta. */}
            {editingId === row.id && draft !== null && (
              <WatcherEditForm
                partNumber={row.partNumber}
                draft={draft}
                busy={busy}
                error={editError}
                onChange={setDraft}
                onSave={() => {
                  void saveEdit(row);
                }}
                onCancel={cancelEdit}
              />
            )}
          </li>
        ))}
      </ul>
    );
  }

  return (
    <div className={styles.screen} data-testid="watchers-screen">
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {/* Aviso de éxito: uno solo a la vez, y solo mientras hay algo que contar. */}
      {status !== null && (
        <p className={styles.status} role="status">
          {status}
        </p>
      )}

      <div className={styles.counterRow}>
        <span
          className={styles.counter}
          data-testid="watcher-counter"
          data-tone={counterTone(rows)}
        >
          {activeCounterLabel(rows)}
        </span>
      </div>

      {/* Los seis chips, en el orden de la spec. El nombre accesible es
          'Etiqueta N' (etiqueta, un espacio, el contador), también a cero. */}
      <div className={styles.chips}>
        {WATCHER_FILTERS.map(({ key, label }) => (
          <button
            key={key}
            type="button"
            className={styles.chip}
            aria-pressed={filter === key}
            onClick={() => setFilter(key)}
          >
            {label}{' '}
            <span className={styles.chipCount}>{watcherFilterCount(rows, key)}</span>
          </button>
        ))}
      </div>

      {actionError !== null && (
        <p className={styles.alert} role="alert">
          {actionError}
        </p>
      )}

      {loading ? (
        <p className={styles.loading} aria-busy="true">
          Cargando watchers…
        </p>
      ) : loadError !== null ? (
        <p className={styles.alert} role="alert">
          {loadError}
        </p>
      ) : (
        renderList()
      )}

      {deleting !== null && (
        <DeleteWatcherModal
          partNumber={deleting.partNumber}
          busy={busy}
          error={deleteError}
          onConfirm={() => {
            void confirmDelete();
          }}
          onCancel={cancelDelete}
        />
      )}
    </div>
  );
}
